toad_implementation.code_blueprint:
canvas {
  size: 800px 500px;
  fill: #003366;
  font-family: "Arial, sans-serif";
}

>govBlue = #003366;
>signalYellow = #FFE600;
>white = #FFFFFF;

rect #headerStripe {
  at: top left of canvas;
  size: 800px 16px;
  fill: >signalYellow;
}

text #hallHeader {
  at: top left of canvas offset 48px 48px;
  content: "BÜRGERAMT // LEITSYSTEM";
  font-size: 20px;
  font-weight: 700;
  color: >signalYellow;
}

rect #wayfindingCard1 {
  at: below #hallHeader offset 32px;
  size: 704px 120px;
  fill: #002244;
  stroke: >white;
  stroke-width: 2px;
  radius: 8px;
}

text #arrow1 {
  at: left center of #wayfindingCard1 offset 32px 0px;
  content: "➔";
  font-size: 48px;
  font-weight: 900;
  color: >signalYellow;
}

text #room1Title {
  at: right of #arrow1 offset 32px;
  content: "ZIMMER 101 - 115: MELDEWESEN";
  font-size: 24px;
  font-weight: 700;
  color: >white;
}

rect #wayfindingCard2 {
  at: below #wayfindingCard1 offset 20px;
  size: 704px 120px;
  fill: #002244;
  stroke: >white;
  stroke-width: 2px;
  radius: 8px;
}

text #arrow2 {
  at: left center of #wayfindingCard2 offset 32px 0px;
  content: "⬆";
  font-size: 48px;
  font-weight: 900;
  color: >signalYellow;
}

text #room2Title {
  at: right of #arrow2 offset 32px;
  content: "AUFZUG • BARRIEREFREIER ZUGANG";
  font-size: 24px;
  font-weight: 700;
  color: >white;
}
